export declare const DDL = "\n-- Matches the package's own declaration: id is required, name and slug are optional, and two\n-- workspaces may share a slug. Asserted by auth-conformance.ts, which auth-postgres also runs.\nCREATE TABLE IF NOT EXISTS \"workspace\" (\n  \"id\" text PRIMARY KEY NOT NULL,\n  \"name\" text,\n  \"slug\" text,\n  \"created_at\" integer NOT NULL DEFAULT (unixepoch() * 1000),\n  \"updated_at\" integer NOT NULL DEFAULT (unixepoch() * 1000)\n);\n\nCREATE TABLE IF NOT EXISTS \"workspace_member\" (\n  \"id\" text PRIMARY KEY NOT NULL,\n  \"workspace_id\" text NOT NULL REFERENCES \"workspace\"(\"id\") ON DELETE CASCADE,\n  \"user_id\" text NOT NULL,\n  \"role_id\" text NOT NULL,\n  \"invited_by\" text,\n  \"created_at\" integer NOT NULL DEFAULT (unixepoch() * 1000)\n);\n\n\nCREATE TABLE IF NOT EXISTS \"workspace_role\" (\n  \"id\" text PRIMARY KEY NOT NULL,\n  \"name\" text NOT NULL,\n  \"workspace_id\" text REFERENCES \"workspace\"(\"id\") ON DELETE CASCADE,\n  \"rank\" integer NOT NULL DEFAULT 0,\n  \"created_at\" integer NOT NULL DEFAULT (unixepoch() * 1000)\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS \"workspace_role_workspace_name_idx\"\n  ON \"workspace_role\" (\"workspace_id\", \"name\");\n\nCREATE TABLE IF NOT EXISTS \"workspace_feature\" (\n  \"id\" text PRIMARY KEY NOT NULL,\n  \"name\" text NOT NULL,\n  \"description\" text,\n  \"workspace_id\" text REFERENCES \"workspace\"(\"id\") ON DELETE CASCADE,\n  \"created_at\" integer NOT NULL DEFAULT (unixepoch() * 1000)\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS \"workspace_feature_workspace_name_idx\"\n  ON \"workspace_feature\" (\"workspace_id\", \"name\");\n\nCREATE TABLE IF NOT EXISTS \"workspace_feature_permission\" (\n  \"id\" text PRIMARY KEY NOT NULL,\n  \"workspace_id\" text REFERENCES \"workspace\"(\"id\") ON DELETE CASCADE,\n  \"role_id\" text NOT NULL REFERENCES \"workspace_role\"(\"id\") ON DELETE CASCADE,\n  \"feature_id\" text NOT NULL REFERENCES \"workspace_feature\"(\"id\") ON DELETE CASCADE,\n  \"allowed\" integer NOT NULL DEFAULT 0,\n  \"created_at\" integer NOT NULL DEFAULT (unixepoch() * 1000)\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS \"workspace_feature_permission_scope_idx\"\n  ON \"workspace_feature_permission\" (\"workspace_id\", \"role_id\", \"feature_id\");\n\n\n\nCREATE TABLE IF NOT EXISTS \"workspace_invitation\" (\n  \"id\" text PRIMARY KEY NOT NULL,\n  \"workspace_id\" text NOT NULL REFERENCES \"workspace\"(\"id\") ON DELETE CASCADE,\n  \"email\" text NOT NULL,\n  \"role_id\" text NOT NULL,\n  \"invited_by_user_id\" text NOT NULL,\n  \"token_hash\" text NOT NULL,\n  \"status\" text NOT NULL DEFAULT 'pending',\n  \"expires_at\" integer NOT NULL,\n  \"accepted_at\" integer,\n  \"accepted_by_user_id\" text,\n  \"created_at\" integer NOT NULL DEFAULT (unixepoch() * 1000),\n  \"updated_at\" integer NOT NULL DEFAULT (unixepoch() * 1000)\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS \"workspace_invitation_pending_email_idx\"\n  ON \"workspace_invitation\" (\"workspace_id\", \"email\")\n  WHERE \"status\" = 'pending';\n\n\n\nCREATE TABLE IF NOT EXISTS \"jwks\" (\n  \"id\" text PRIMARY KEY NOT NULL,\n  \"public_key\" text NOT NULL,\n  \"private_key\" text NOT NULL,\n  \"created_at\" integer NOT NULL,\n  \"expires_at\" integer,\n  \"alg\" text,\n  \"crv\" text\n);\n\nCREATE TABLE IF NOT EXISTS \"oauthClient\" (\n  \"id\" text PRIMARY KEY NOT NULL,\n  \"client_id\" text NOT NULL UNIQUE,\n  \"client_secret\" text,\n  \"client_discovery_id\" text,\n  \"disabled\" integer DEFAULT 0,\n  \"skip_consent\" integer,\n  \"enable_end_session\" integer,\n  \"subject_type\" text,\n  \"scopes\" text,\n  \"client_credentials_scopes\" text,\n  \"user_id\" text REFERENCES \"user\"(\"id\"),\n  \"created_at\" integer,\n  \"updated_at\" integer,\n  \"name\" text,\n  \"uri\" text,\n  \"icon\" text,\n  \"contacts\" text,\n  \"tos\" text,\n  \"policy\" text,\n  \"software_id\" text,\n  \"software_version\" text,\n  \"software_statement\" text,\n  \"redirect_uris\" text NOT NULL,\n  \"post_logout_redirect_uris\" text,\n  \"backchannel_logout_uri\" text,\n  \"backchannel_logout_session_required\" integer,\n  \"token_endpoint_auth_method\" text,\n  \"application_type\" text,\n  \"jwks\" text,\n  \"jwks_uri\" text,\n  \"grant_types\" text,\n  \"response_types\" text,\n  \"require_pkce\" integer,\n  \"dpop_bound_access_tokens\" integer DEFAULT 0,\n  \"reference_id\" text,\n  \"metadata\" text\n);\n\nCREATE TABLE IF NOT EXISTS \"oauthResource\" (\n  \"id\" text PRIMARY KEY NOT NULL,\n  \"identifier\" text NOT NULL UNIQUE,\n  \"name\" text NOT NULL,\n  \"access_token_ttl\" integer,\n  \"refresh_token_ttl\" integer,\n  \"signing_algorithm\" text,\n  \"signing_key_id\" text,\n  \"allowed_scopes\" text,\n  \"custom_claims\" text,\n  \"dpop_bound_access_tokens_required\" integer DEFAULT 0,\n  \"disabled\" integer DEFAULT 0,\n  \"created_at\" integer,\n  \"updated_at\" integer,\n  \"policy_version\" integer DEFAULT 1,\n  \"metadata\" text\n);\n\nCREATE TABLE IF NOT EXISTS \"oauthClientResource\" (\n  \"id\" text PRIMARY KEY NOT NULL,\n  \"client_id\" text NOT NULL REFERENCES \"oauthClient\"(\"client_id\") ON DELETE CASCADE,\n  \"resource_id\" text NOT NULL REFERENCES \"oauthResource\"(\"identifier\") ON DELETE CASCADE,\n  \"metadata\" text,\n  \"created_at\" integer\n);\n\nCREATE TABLE IF NOT EXISTS \"oauthRefreshToken\" (\n  \"id\" text PRIMARY KEY NOT NULL,\n  \"token\" text NOT NULL UNIQUE,\n  \"client_id\" text NOT NULL REFERENCES \"oauthClient\"(\"client_id\"),\n  \"session_id\" text REFERENCES \"session\"(\"id\") ON DELETE SET NULL,\n  \"user_id\" text NOT NULL REFERENCES \"user\"(\"id\"),\n  \"reference_id\" text,\n  \"authorization_code_id\" text,\n  \"resources\" text,\n  \"requested_user_info_claims\" text,\n  \"expires_at\" integer,\n  \"created_at\" integer,\n  \"revoked\" integer,\n  \"rotated_at\" integer,\n  \"rotation_replay_response\" text,\n  \"rotation_replay_expires_at\" integer,\n  \"auth_time\" integer,\n  \"confirmation\" text,\n  \"scopes\" text NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS \"oauthAccessToken\" (\n  \"id\" text PRIMARY KEY NOT NULL,\n  \"token\" text UNIQUE,\n  \"client_id\" text NOT NULL REFERENCES \"oauthClient\"(\"client_id\"),\n  \"session_id\" text REFERENCES \"session\"(\"id\") ON DELETE SET NULL,\n  \"user_id\" text REFERENCES \"user\"(\"id\"),\n  \"reference_id\" text,\n  \"authorization_code_id\" text,\n  \"resources\" text,\n  \"requested_user_info_claims\" text,\n  \"refresh_id\" text REFERENCES \"oauthRefreshToken\"(\"id\"),\n  \"expires_at\" integer,\n  \"created_at\" integer,\n  \"revoked\" integer,\n  \"confirmation\" text,\n  \"scopes\" text NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS \"oauthConsent\" (\n  \"id\" text PRIMARY KEY NOT NULL,\n  \"client_id\" text NOT NULL REFERENCES \"oauthClient\"(\"client_id\"),\n  \"user_id\" text REFERENCES \"user\"(\"id\"),\n  \"reference_id\" text,\n  \"resources\" text,\n  \"requested_user_info_claims\" text,\n  \"scopes\" text NOT NULL,\n  \"created_at\" integer,\n  \"updated_at\" integer\n);\n\nCREATE TABLE IF NOT EXISTS \"oauthClientAssertion\" (\n  \"id\" text PRIMARY KEY NOT NULL,\n  \"expires_at\" integer NOT NULL\n);\n\n\nCREATE TABLE IF NOT EXISTS \"user\" (\n  \"id\" text PRIMARY KEY NOT NULL,\n  \"name\" text NOT NULL,\n  \"email\" text NOT NULL UNIQUE,\n  \"email_verified\" integer NOT NULL DEFAULT 0,\n  \"image\" text,\n  \"created_at\" integer NOT NULL DEFAULT (unixepoch() * 1000),\n  \"updated_at\" integer NOT NULL DEFAULT (unixepoch() * 1000)\n);\n\nCREATE TABLE IF NOT EXISTS \"session\" (\n  \"id\" text PRIMARY KEY NOT NULL,\n  \"expires_at\" integer NOT NULL,\n  \"token\" text NOT NULL UNIQUE,\n  \"created_at\" integer NOT NULL DEFAULT (unixepoch() * 1000),\n  \"updated_at\" integer NOT NULL DEFAULT (unixepoch() * 1000),\n  \"ip_address\" text,\n  \"user_agent\" text,\n  \"user_id\" text NOT NULL REFERENCES \"user\"(\"id\") ON DELETE CASCADE\n);\n\nCREATE INDEX IF NOT EXISTS \"session_userId_idx\" ON \"session\" (\"user_id\");\n\nCREATE TABLE IF NOT EXISTS \"account\" (\n  \"id\" text PRIMARY KEY NOT NULL,\n  \"account_id\" text NOT NULL,\n  \"provider_id\" text NOT NULL,\n  \"user_id\" text NOT NULL REFERENCES \"user\"(\"id\") ON DELETE CASCADE,\n  \"access_token\" text,\n  \"refresh_token\" text,\n  \"id_token\" text,\n  \"access_token_expires_at\" integer,\n  \"refresh_token_expires_at\" integer,\n  \"scope\" text,\n  \"password\" text,\n  \"created_at\" integer NOT NULL DEFAULT (unixepoch() * 1000),\n  \"updated_at\" integer NOT NULL DEFAULT (unixepoch() * 1000)\n);\n\nCREATE INDEX IF NOT EXISTS \"account_userId_idx\" ON \"account\" (\"user_id\");\n\nCREATE TABLE IF NOT EXISTS \"verification\" (\n  \"id\" text PRIMARY KEY NOT NULL,\n  \"identifier\" text NOT NULL,\n  \"value\" text NOT NULL,\n  \"expires_at\" integer NOT NULL,\n  \"created_at\" integer NOT NULL DEFAULT (unixepoch() * 1000),\n  \"updated_at\" integer NOT NULL DEFAULT (unixepoch() * 1000)\n);\n\nCREATE INDEX IF NOT EXISTS \"verification_identifier_idx\" ON \"verification\" (\"identifier\");\n";
export declare const SYSTEM_ROLES_SEED_DDL = "\nINSERT INTO \"workspace_role\" (\"id\", \"name\", \"workspace_id\", \"rank\")\nVALUES\n  ('admin', 'admin', NULL, 2),\n  ('editor', 'editor', NULL, 1),\n  ('sender', 'sender', NULL, 0)\nON CONFLICT (\"id\") DO NOTHING;\n";
